<?php
require '../config/app.php'; require_role('patient'); require '../config/payment.php'; header('Content-Type: application/json');
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['ok'=>false,'message'=>'Method not allowed']);exit;}check_csrf();$id=(int)($_GET['id']??0);$uid=user()['id'];
if(!razorpay_configured()){echo json_encode(['ok'=>false,'message'=>'Razorpay keys are not configured.']);exit;}
$st=$pdo->prepare("SELECT a.id,t.name test_name,t.price,u.name customer_name,u.email,u.phone,p.status,p.id payment_id FROM appointments a JOIN diagnostic_tests t ON t.id=a.test_id JOIN users u ON u.id=a.patient_id JOIN payments p ON p.appointment_id=a.id WHERE a.id=? AND a.patient_id=?");$st->execute([$id,$uid]);$a=$st->fetch();if(!$a){echo json_encode(['ok'=>false,'message'=>'Appointment not found.']);exit;}if($a['status']==='Paid'){echo json_encode(['ok'=>false,'message'=>'Payment already completed.']);exit;}
$payload=json_encode(['amount'=>(int)round($a['price']*100),'currency'=>'INR','receipt'=>'DLAB-'.$a['id'].'-'.time(),'notes'=>['appointment_id'=>(string)$a['id'],'patient_id'=>(string)$uid]]);
$ch=curl_init(razorpay_base_url().'/orders');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$payload,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_USERPWD=>$razorpayKeyId.':'.$razorpayKeySecret,CURLOPT_TIMEOUT=>20]);$resp=curl_exec($ch);$err=curl_error($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($err||$code<200||$code>=300){echo json_encode(['ok'=>false,'message'=>'Could not create payment order. '.($err?:'Gateway returned HTTP '.$code)]);exit;}
$order=json_decode($resp,true);if(empty($order['id'])){echo json_encode(['ok'=>false,'message'=>'Invalid payment gateway response.']);exit;}
$up=$pdo->prepare("UPDATE payments SET gateway_order_id=?,method='Online',status='Pending' WHERE id=?");$up->execute([$order['id'],$a['payment_id']]);
echo json_encode(['ok'=>true,'key'=>$razorpayKeyId,'order_id'=>$order['id'],'amount'=>$order['amount'],'description'=>'Payment for '.$a['test_name'],'customer'=>['name'=>$a['customer_name'],'email'=>$a['email'],'phone'=>$a['phone']]]);
